// Внутренняя библиотека заданий на исполнительные функции. Это не отдельная
// продаваемая неделя: части библиотеки встроены в недели 4 и 5 курса.
import {
  choice as choiceBuilder,
  memory as memoryBuilder,
  quiz as quizBuilder,
  sequence as sequenceBuilder,
  symbolOption,
} from './school-prep-mission-builders.js';

const TONES = ['purple', 'blue', 'cyan', 'orange', 'green', 'pink'];
const options = (items) => items.map((item, index) => {
  const [label, symbol = label] = Array.isArray(item) ? item : [item];
  return symbolOption(`o${index}`, label, symbol, TONES[index % TONES.length]);
});

function pick(id, chapter, skill, title, prompt, items, correct, hint, mode = 'single') {
  const answer = correct.map((index) => items[index][0]).join(' и ');
  return choiceBuilder(id, chapter, skill, title, prompt, options(items), correct.map((index) => `o${index}`), hint, `Верно: ${answer}. Ты удержал правило и проверил ответ.`, mode);
}
function order(id, chapter, skill, title, prompt, items, correct, hint) {
  return sequenceBuilder(id, chapter, skill, title, prompt, options(items), correct.map((index) => `o${index}`), hint, 'Верно! Порядок восстановлен без потери шагов инструкции.');
}
function pairs(id, chapter, skill, title, prompt, items) {
  return memoryBuilder(id, chapter, skill, title, prompt, items.flatMap(([pair, left, right]) => [{ pair, label: left, emoji: left }, { pair, label: right, emoji: right }]), 'Все смысловые пары найдены. Память удержала и образ, и правило связи.');
}
function action(id, chapter, skill, title, prompt, actions) {
  return { id, type: 'action', chapter, skill, title, prompt, actions: actions.map(([actionTitle, text, visual = 'idea']) => ({ title: actionTitle, text, visual })), success: 'Практическая часть выполнена. Назови взрослому правило, которое помогло не торопиться.' };
}
function sort(id, chapter, skill, title, prompt, groups, items, hint) {
  return { id, type: 'sort', chapter, skill, title, prompt, groups: groups.map(([groupId, label, emoji]) => ({ id: groupId, label, emoji })), items: items.map(([label, group, emoji = label]) => ({ label, group, emoji })), hint, success: 'Верно! Все сигналы распределены по действующему правилу.' };
}
function recall(id, chapter, skill, title, prompt, study, answers, correct, hint) {
  return { id, type: 'recall', chapter, skill, title, prompt, study: study.map(([label, visual]) => ({ label, visual })), options: answers.map(([label, visual], index) => ({ id: `o${index}`, label, visual })), correct: [`o${correct}`], hint, success: `Верно: ${answers[correct][0]}. Ты восстановил информацию после паузы.` };
}
function grid(id, chapter, skill, title, prompt, cells, correct, hint) {
  return { id, type: 'attention-grid', chapter, skill, title, prompt, cells: cells.map(([label, symbol, tone], index) => ({ id: `c${index}`, label, symbol, tone })), correct: correct.map((index) => `c${index}`), hint, success: 'Цель найдена точно: ни один похожий отвлекающий знак не попал в ответ.' };
}
function goNoGo(id, chapter, skill, title, prompt, cues, rule, hint) {
  return { id, type: 'go-no-go', chapter, skill, title, prompt, cues: cues.map(([label, symbol, shouldTap]) => ({ label, symbol, shouldTap })), rule, hint, success: 'Серия завершена: ты успевал остановиться перед сигналом-ловушкой.' };
}
function switchRule(id, chapter, skill, title, prompt, rounds, hint) {
  return { id, type: 'rule-switch', chapter, skill, title, prompt, rounds: rounds.map(([rule, stimulus, answers, correct]) => ({ rule, stimulus, options: answers.map((label, index) => ({ id: `r${index}`, label })), correct: `r${correct}` })), hint, success: 'Все переключения выполнены: новое правило включалось вовремя.' };
}
function exam(id, chapter, skill, title, prompt, questions) {
  return quizBuilder(id, chapter, skill, title, prompt, questions.map(([questionPrompt, answers, correct]) => ({ prompt: questionPrompt, options: answers.map((label, index) => ({ id: `q${index}`, label })), correct: `q${correct}` })), 'Проверка завершена. Результат первой попытки сохранён в отчёте для родителя.');
}
