function prepareDay(dayId, missions) {
  const design = dayDesign[dayId];
  const bonusIds = new Set(design.bonusIds);
  const prepared = missions.map((mission) => ({ ...mission, route: bonusIds.has(mission.id) ? 'bonus' : 'core' }));
  const diagnostic = prepared.find((mission) => mission.type === 'quiz');
  return [...prepared.filter((mission) => mission.route === 'core' && mission !== diagnostic), diagnostic, ...prepared.filter((mission) => mission.route === 'bonus')];
}

